import { useState, useEffect } from 'react';
import { fetchCertificates, createCertificate, updateCertificate, deleteCertificate } from '../api';
import DashboardLayout from '../components/DashboardLayout';
import DataTable from '../components/DataTable';
import Modal from '../components/Modal';
import { Plus, Edit, Trash2, Eye, Printer, Download } from 'lucide-react';
import * as XLSX from 'xlsx';
import { mapImportRows, CERTIFICATE_FIELD_ALIASES } from '../utils/importUtils';

const initialFormData = {
  function_type: 'Marriage',
  function_date: '',
  function_time: '',
  booking_date: '',
  receipt_no: '',
  bridegroom: '',
  bridegroom_so: '',
  bride: '',
  bride_do: '',
  requestor_name: ''
};

const formatTime12 = (timeStr) => {
  if (!timeStr) return '';
  const normalized = String(timeStr).trim();
  if (/am|pm/i.test(normalized)) return normalized;
  const match = normalized.match(/^(\d{1,2}):(\d{2})/);
  if (!match) return normalized;
  let hours = parseInt(match[1], 10);
  const minutes = match[2];
  const period = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12 || 12;
  return `${hours}:${minutes} ${period}`;
};

export default function Certificate() {
  const [certificates, setCertificates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewOpen, setIsViewOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [viewData, setViewData] = useState(null);
  const [isConfirmDeleteOpen, setIsConfirmDeleteOpen] = useState(false);
  const [deleteId, setDeleteId] = useState(null);

  const [formData, setFormData] = useState(initialFormData);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const data = await fetchCertificates();
      setCertificates(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleImportFile = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const bstr = event.target.result;
      const workbook = XLSX.read(bstr, { type: 'binary' });
      const sheetName = workbook.SheetNames[0];
      const sheet = workbook.Sheets[sheetName];
      const jsonData = XLSX.utils.sheet_to_json(sheet);

      const newCerts = mapImportRows(jsonData, {
        defaults: initialFormData,
        aliases: CERTIFICATE_FIELD_ALIASES,
        requiredFields: ['bridegroom', 'bride'],
      });

      if (newCerts.length === 0) {
        alert('No valid certificate records found. Check column headers and required fields.');
        return;
      }

      if (window.confirm(`Import ${newCerts.length} records from ${file.name}?`)) {
        try {
          setLoading(true);
          for (let cert of newCerts) {
            await createCertificate(cert);
          }
          alert('Import successful!');
          loadData();
        } catch (err) {
          alert('Error during import: ' + err.message);
        } finally {
          setLoading(false);
        }
      }
    };
    reader.readAsBinaryString(file);
    e.target.value = '';
  };

  const handleOpenCreate = () => {
    const maxRec = certificates.reduce((max, curr) => {
      const num = parseInt(curr.receipt_no);
      return isNaN(num) ? max : Math.max(max, num);
    }, 0);

    setFormData({
      ...initialFormData,
      receipt_no: (maxRec + 1).toString()
    });
    setEditingId(null);
    setIsModalOpen(true);
  };

  const handleOpenEdit = (row) => {
    setFormData({ ...row });
    setEditingId(row.id);
    setIsModalOpen(true);
  };

  const handleOpenView = (row) => {
    setViewData(row);
    setIsViewOpen(true);
  };

  const handlePrint = (row) => {
    const formatDate = (dateStr) => {
      if (!dateStr) return '';
      const date = new Date(dateStr);
      return date.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }).replace(/ /g, '-');
    };

    const getDayName = (dateStr) => {
      if (!dateStr) return '';
      const date = new Date(dateStr);
      return date.toLocaleDateString('en-US', { weekday: 'long' });
    };

    const printContent = `
      <div style="width: 100%; font-family: 'Times New Roman', Times, serif; position: relative; min-height: 1000px; color: #333;">
        <!-- Header Image & Styling -->
        <div style="background-color: #ff0000; padding: 50px 10px; text-align: center; color: white;">
          <h1 style="margin: 0; font-size: 2.2rem; letter-spacing: 1px; font-weight: 900;">SRI LAKSHMI SRUNGARA VALLABHA FUNCTION HALL</h1>
        </div>

        <div style="display: flex; justify-content: space-around; background: white; padding: 12px; width: 92%; margin: -20px auto 30px; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); border: 1px solid #ff0000; font-size: 0.85rem; font-weight: bold;">
          <span><svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="15" height="17" viewBox="0 0 878 1000">
  <image id="location" width="878" height="1000" xlink:href="data:img/png;base64,"/>
</svg> Main Road , Divili</span>
          <span>📞 +91 9866544270</span>
          <span>✉️ srilakshmisrungaravallabha@gmail.com</span>
        </div>

        <!-- Certificate Content -->
        <div style="padding: 0 60px; position: relative; z-index: 1;">
          <h2 style="text-align: center; color: #2e7d32; text-decoration: underline; margin-bottom: 5px; font-size: 1.8rem;">MARRIAGE CERTIFICATE</h2>
          <h3 style="text-align: center; text-decoration: underline; margin-bottom: 40px; font-weight: bold;">TO WHOM IT MAY CONCERN</h3>

          <div style="font-size: 1.2rem; line-height: 2; text-align: left;">
            <p style="text-align: justify; text-indent: 50px;">This is to certify that the marriage between the following Bride and Bridgeroom has been performed at our Function Hall on 
               <span style="font-weight: bold; text-decoration: underline; text-transform: capitalize;">${formatDate(row.function_date)}</span> 
               Under Receipt No. <span style="font-weight: bold; text-decoration: underline;  text-transform: capitalize;">${row.receipt_no}</span> 
               Booked on <span style="font-weight: bold; text-decoration: underline;  text-transform: capitalize;">${formatDate(row.booking_date)}</span>
            </p>

            <div style="margin:0;">
              <p style="margin:0;">Bridegroom : <span style="margin-left: 10px; font-weight: bold; color: #1e3a8a; text-decoration: underline; text-transform: capitalize;">Chy. ${row.bridegroom}</span></p>
              <div style="margin-left: 105px;">Son Of <span style="font-weight: bold; color: #1e3a8a; text-decoration: underline; text-transform: capitalize;">${row.bridegroom_so}</span></div>
              <div style="margin-top: 20px;">Bride : <span style="margin-left: 55px; font-weight: bold; color: #1e3a8a; text-decoration: underline; text-transform: capitalize;">Chy. Sow. ${row.bride}</span></div>
              <div style="margin-left: 105px;">Daughter Of <span style="font-weight: bold; color: #1e3a8a; text-decoration: underline; text-transform: capitalize;">${row.bride_do}</span></div>
            </div>

            <p>The marriage was held successfully at our Function Hall at <span style="font-weight: bold; text-decoration: underline;">${formatTime12(row.function_time)}</span>
            On <span style="font-weight: bold; text-decoration: underline;  text-transform: capitalize;">${formatDate(row.function_date)} {${getDayName(row.function_date)}}</span></p>
            
            <p style="margin-top: 30px;">This certificate has been issued on the request of Sri / Smt. <span style="font-weight: bold; color: #1e3a8a; text-decoration: underline; text-transform: capitalize;">${row.requestor_name || row.bride_do}</span> and on verification of the records</p>
          </div>

          <!-- Bottom Signature Area -->
          <div style="margin-top: 80px; display: flex; justify-content: space-between; align-items: flex-end;">
            <div>
              <p style="font-weight: bold;">Divili,</p>
              <p style="font-weight: bold;">Dt:- ${formatDate(new Date())}</p>
            </div>
            <div style="text-align: right; color: #1e3a8a;">
              <p style="font-weight: bold; margin-bottom: 0; display:none">For Sri Lakshmi Srungara Vallabha Function Hall</p>
              <div style="height: 50px;"></div> <!-- Signature Space -->
              <p style="font-weight: bold; margin-top: 0;">Proprietor</p>
            </div>
          </div>
        </div>

        <!-- Watermark -->
        <div style="position: absolute;top: 63%;left: 52%;transform: translate(-50%, -50%);opacity: 0.27;z-index: 0;width: 450px;pointer-events: none;">
          <img style="height: 400px;" src="./src/assets/logo.png" alt="logo" />
        </div>

        <!-- Footer Tagline -->
        <div style="position: fixed; bottom: 20px; width: 100%; text-align: center; border-top: 1px solid #ddd; padding-top: 10px; font-size: 0.8rem;">
          <p style="margin: 0; font-weight: bold;">Sri Lakshmi Srungara Vallabha Function Hall | Your Perfect Venue for Every Occasion</p>
          <p style="margin: 2px 0 0; color: #777;">Weddings | Receptions | Corporate Events | Birthday Parties | Social Gatherings</p>
        </div>
      </div>
    `;

    let iframe = document.getElementById('print-iframe');
    if (!iframe) {
      iframe = document.createElement('iframe');
      iframe.id = 'print-iframe';
      iframe.style.position = 'fixed';
      iframe.style.right = '0';
      iframe.style.bottom = '0';
      iframe.style.width = '0';
      iframe.style.height = '0';
      iframe.style.border = '0';
      document.body.appendChild(iframe);
    }

    const iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write('<html><head><title>Marriage Certificate</title>');
    iframeDoc.write(`
      <style>
        @page { size: A4; margin: 0; }
        body { margin: 0; padding: 0; -webkit-print-color-adjust: exact; print-color-adjust: exact; font-family: 'Times New Roman', Times, serif; }
      </style>
    `);
    iframeDoc.write('</head><body>');
    iframeDoc.write(printContent);
    iframeDoc.write('</body></html>');
    iframeDoc.close();

    setTimeout(() => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
    }, 500);
  };

  const handleDeleteClick = (id) => {
    setDeleteId(id);
    setIsConfirmDeleteOpen(true);
  };

  const handleConfirmDelete = async () => {
    try {
      await deleteCertificate(deleteId);
      setIsConfirmDeleteOpen(false);
      setDeleteId(null);
      loadData();
    } catch (err) {
      alert(err.message);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingId) {
        await updateCertificate(editingId, formData);
      } else {
        await createCertificate(formData);
      }
      setIsModalOpen(false);
      setFormData(initialFormData);
      loadData();
    } catch (err) {
      alert(err.message);
    }
  };

  const columns = [
    { header: 'Receipt No', accessor: 'receipt_no' },
    { header: 'Bridegroom', accessor: 'bridegroom' },
    { header: 'Bride', accessor: 'bride' },
    { header: 'Function Date', accessor: 'function_date', cell: (row) => row.function_date ? new Date(row.function_date).toLocaleDateString() : '-' },
    {
      header: 'Action',
      cell: (row) => (
        <div style={{ display: 'flex', gap: '0.5rem' }}>
          <button className="btn-icon" onClick={() => handlePrint(row)} title="Print" style={{ color: '#3b82f6' }}>
            <Printer size={18} />
          </button>
          <button className="btn-icon" onClick={() => handleOpenView(row)} title="View" style={{ color: 'var(--primary)' }}>
            <Eye size={18} />
          </button>
          <button className="btn-icon" onClick={() => handleOpenEdit(row)} title="Edit" style={{ color: 'var(--text-main)' }}>
            <Edit size={18} />
          </button>
          <button className="btn-icon" onClick={() => handleDeleteClick(row.id)} title="Delete" style={{ color: '#ef4444' }}>
            <Trash2 size={18} />
          </button>
        </div>
      )
    }
  ];

  const headerAction = (
    <div style={{ display: 'flex', gap: '0.75rem' }}>
      <input type="file" id="import-cert-file" accept=".csv,.xlsx,.xls" style={{ display: 'none' }} onChange={handleImportFile} />
      <label htmlFor="import-cert-file" className="btn btn-secondary" style={{ cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
        <Download size={16} style={{ transform: 'rotate(180deg)' }} /> Import (CSV/Excel)
      </label>
      <button className="btn btn-primary" onClick={handleOpenCreate}>
        <Plus size={16} /> Create Certificate
      </button>
    </div>
  );

  return (
    <DashboardLayout title="Certificate Issuance" headerAction={headerAction}>
      {loading ? <p>Loading...</p> : <DataTable columns={columns} data={certificates} />}

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? "Edit Certificate" : "New Certificate"}>
        <form onSubmit={handleSubmit}>
          <div className="form-grid">
            <div className="form-group">
              <label className="form-label">Receipt No</label>
              <input type="text" className="form-control" value={formData.receipt_no} readOnly style={{ backgroundColor: 'var(--bg-main)', cursor: 'not-allowed' }} />
            </div>
            <div className="form-group">
              <label className="form-label">Booking Date</label>
              <input type="date" className="form-control" value={formData.booking_date} onChange={e => setFormData({ ...formData, booking_date: e.target.value })} required />
            </div>
            <div className="form-group">
              <label className="form-label">Function Date</label>
              <input type="date" className="form-control" value={formData.function_date} onChange={e => setFormData({ ...formData, function_date: e.target.value })} required />
            </div>
            <div className="form-group">
              <label className="form-label">Function Time</label>
              <input type="time" className="form-control" value={formData.function_time} onChange={e => setFormData({ ...formData, function_time: e.target.value })} required />
            </div>
            <div className="form-group">
              <label className="form-label">Bridegroom Name</label>
              <input type="text" className="form-control" value={formData.bridegroom} onChange={e => setFormData({ ...formData, bridegroom: e.target.value })} required />
            </div>
            <div className="form-group">
              <label className="form-label">Bridegroom S/O</label>
              <input type="text" className="form-control" value={formData.bridegroom_so} onChange={e => setFormData({ ...formData, bridegroom_so: e.target.value })} required />
            </div>
            <div className="form-group">
              <label className="form-label">Bride Name</label>
              <input type="text" className="form-control" value={formData.bride} onChange={e => setFormData({ ...formData, bride: e.target.value })} required />
            </div>
            <div className="form-group">
              <label className="form-label">Bride D/O (Father's Name)</label>
              <input type="text" className="form-control" value={formData.bride_do} onChange={e => setFormData({ ...formData, bride_do: e.target.value })} required />
            </div>
            <div className="form-group" style={{ gridColumn: '1 / -1' }}>
              <label className="form-label">Requestor Name (Sri / Smt.)</label>
              <input type="text" className="form-control" value={formData.requestor_name} onChange={e => setFormData({ ...formData, requestor_name: e.target.value })} required />
            </div>
          </div>
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '1rem', marginTop: '1.5rem' }}>
            <button type="button" className="btn btn-secondary" onClick={() => setIsModalOpen(false)}>Cancel</button>
            <button type="submit" className="btn btn-primary">{editingId ? "Update" : "Save"}</button>
          </div>
        </form>
      </Modal>

      <Modal isOpen={isViewOpen} onClose={() => setIsViewOpen(false)} title="Certificate Preview">
        {viewData && (
          <div style={{ display: 'grid', gap: '1rem' }}>
            <div style={{ padding: '1rem', backgroundColor: 'var(--bg-main)', borderRadius: '0.5rem' }}>
              <h4 style={{ marginBottom: '0.5rem', color: 'var(--primary)' }}>Marriage Details</h4>
              <p><strong>Receipt No:</strong> {viewData.receipt_no}</p>
              <p><strong>Bridegroom:</strong> {viewData.bridegroom}</p>
              <p><strong>Bride:</strong> {viewData.bride}</p>
              <p><strong>Date:</strong> {viewData.function_date} ({formatTime12(viewData.function_time)})</p>
            </div>
            <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '1rem' }}>
              <button type="button" className="btn btn-secondary" onClick={() => setIsViewOpen(false)}>Close</button>
            </div>
          </div>
        )}
      </Modal>

      {/* Delete Confirmation Modal */}
      <Modal isOpen={isConfirmDeleteOpen} onClose={() => setIsConfirmDeleteOpen(false)} title="Confirm Delete">
        <div style={{ display: 'grid', gap: '1rem' }}>
          <p>Are you sure you want to delete this certificate record? This action cannot be undone.</p>
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '1rem', marginTop: '1rem' }}>
            <button type="button" className="btn btn-secondary" onClick={() => setIsConfirmDeleteOpen(false)}>Cancel</button>
            <button type="button" className="btn btn-primary" style={{ backgroundColor: 'var(--danger)' }} onClick={handleConfirmDelete}>Delete</button>
          </div>
        </div>
      </Modal>
    </DashboardLayout>
  );
}
